// scripts/render/format.ts
function monogram(s3) {
  return String(s3).split(/\s+/).map((w3) => w3.replace(/[^A-Za-z0-9]/g, "")[0]).filter(Boolean).slice(0, 2).join("").toUpperCase();
}
function relativeTime(iso) {
  if (!iso) return "";
  const t4 = new Date(iso).getTime();
  if (Number.isNaN(t4)) return "";
  const diff = Math.max(0, Date.now() - t4);
  const m4 = Math.floor(diff / 6e4);
  if (m4 < 1) return "just now";
  if (m4 < 60) return `${m4}m ago`;
  const h3 = Math.floor(m4 / 60);
  if (h3 < 24) return `${h3}h ago`;
  const d3 = Math.floor(h3 / 24);
  if (d3 < 7) return `${d3}d ago`;
  const w3 = Math.floor(d3 / 7);
  if (w3 < 5) return `${w3}w ago`;
  return new Date(iso).toLocaleDateString(void 0, { month: "short", day: "numeric" });
}
function formatFollowers(n3) {
  if (!n3) return "";
  if (n3 >= 1e6) return (n3 / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
  if (n3 >= 1e3) return Math.round(n3 / 1e3) + "K";
  return String(n3);
}
function cssKey(a3) {
  return `${a3.artist}__${a3.name}`.replace(/[^A-Za-z0-9_]/g, "_");
}

